Repair the following complete CommonJS module. Return a corrected complete source file.

`applyFieldUpdates(state, updates)` accepts a non-null, non-array state object whose own keys are safe keys and whose values are scalars: `null`, strings, booleans, or finite numbers. Safe keys are non-empty strings except `"__proto__"`, `"constructor"`, and `"prototype"`. `updates` must be an array. Invalid top-level input or invalid state fields must throw `TypeError`.

Each valid update is `{ key, value }`, with a safe string key and a scalar value. Malformed updates and updates for keys not already owned by `state` are ignored. Apply valid updates in order, so the last update for a key wins. Falsy values including `false`, `0`, `""`, and `null` must be applied. Return a fresh object and never mutate the inputs. Empty updates return a shallow scalar copy. Export exactly `{ applyFieldUpdates }`.

Known-bad source:
```javascript
const blocked = new Set(['__proto__', 'constructor', 'prototype']);

function isSafeKey(key) {
  return typeof key === 'string' && key.length > 0 && !blocked.has(key);
}

function isScalar(value) {
  return value === null || typeof value === 'string' || typeof value === 'boolean' ||
    (typeof value === 'number' && Number.isFinite(value));
}

function applyFieldUpdates(state, updates) {
  if (!state || typeof state !== 'object' || Array.isArray(state) || !Array.isArray(updates)) {
    throw new TypeError('invalid input');
  }
  for (const key of Object.keys(state)) {
    if (!isSafeKey(key) || !isScalar(state[key])) throw new TypeError('invalid state');
  }

  const result = { ...state };
  for (const update of updates) {
    if (update && typeof update === 'object' && isSafeKey(update.key) &&
        isScalar(update.value) && Object.prototype.hasOwnProperty.call(state, update.key) && update.value) {
      result[update.key] = update.value;
    }
  }
  return result;
}

module.exports = { applyFieldUpdates };
```

