'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['applyFieldUpdates']);
const { applyFieldUpdates } = api;

const state = Object.freeze({ text: 'old', enabled: true, count: 9, nullable: 'value' });
const updates = Object.freeze([
  Object.freeze({ key: 'text', value: '' }),
  Object.freeze({ key: 'enabled', value: false }),
  Object.freeze({ key: 'count', value: 0 }),
  Object.freeze({ key: 'nullable', value: null }),
  Object.freeze({ key: 'missing', value: 'ignored' }),
  Object.freeze({ key: 'count', value: 3 }),
  Object.freeze({ key: 'count', value: 0 }),
  Object.freeze({ key: '__proto__', value: 'ignored' }),
  Object.freeze({ key: 'text', value: Infinity }),
  null
]);
const result = applyFieldUpdates(state, updates);
assert.deepEqual(result, { text: '', enabled: false, count: 0, nullable: null });
assert.notStrictEqual(result, state);
assert.deepEqual(state, { text: 'old', enabled: true, count: 9, nullable: 'value' });

const copy = applyFieldUpdates(state, []);
assert.deepEqual(copy, state);
assert.notStrictEqual(copy, state);
assert.deepEqual(applyFieldUpdates({}, [{ key: 'x', value: 1 }]), {});

for (const badState of [null, [], 'x', 1]) {
  assert.throws(() => applyFieldUpdates(badState, []), TypeError);
}
assert.throws(() => applyFieldUpdates({}, null), TypeError);
for (const badState of [
  { '': 1 },
  { constructor: 1 },
  { prototype: 1 },
  { nested: {} },
  { bad: NaN },
  { bad: Infinity },
  { bad: undefined }
]) {
  assert.throws(() => applyFieldUpdates(badState, []), TypeError);
}

const nullPrototypeState = Object.create(null);
nullPrototypeState.x = 1;
assert.deepEqual(applyFieldUpdates(nullPrototypeState, [{ key: 'x', value: 2 }]), { x: 2 });

